def present(self) -> None:
    """A written or restored scene releases its same deferred source work."""
    self.state = PresentedFrame()
    self.presented.set()
    callbacks = tuple(self.callbacks)
    self.callbacks.clear()
    for owner, callback in callbacks:
        if owner.is_attached:
            owner.call_later(callback)

def present(self, modal) -> None:
    self._modal = ref(modal)
    self.view.app.push_screen(modal)

def present(self, prompt, entry):
    super().present(prompt, entry)
    prompt.shell_mode = True

async def present(self, conversation: Conversation) -> None:
    if self.directory_watcher is not None:
        conversation.call_after_refresh(self.directory_watcher.notify_if_visible)
    if self.shell is not None:
        conversation._shell = self.shell
        await self.shell.attach(conversation)
    if self.agent is not None:
        conversation.agent = self.agent
        conversation.bind_agent(self.agent)

